WITH with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM payments), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessions_payments AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT s.id, s.order_id, s.method, s.amount, s.status, s.prev_paid_at, s.session_id, (SELECT SUM(x.quantity) FROM order_items x WHERE x.order_id = s.order_id) AS sum_order_item_quantity FROM sessions_payments s ORDER BY prev_paid_at DESC NULLS LAST;
